CREATE FUNCTION app_audit_actor_ref(p_user uuid) RETURNS text
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    DECLARE
      s bytea;
    BEGIN
      IF p_user IS NULL THEN
        RETURN NULL;
      END IF;
      INSERT INTO audit_actor_salt (user_id, salt) VALUES (p_user, gen_random_bytes(32))
        ON CONFLICT (user_id) DO NOTHING;
      SELECT a.salt INTO s FROM audit_actor_salt a WHERE a.user_id = p_user;
      RETURN encode(sha256(s || uuid_send(p_user)), 'hex');
    END
  $$;--> statement-breakpoint
CREATE FUNCTION app_audit_actor_ref_matches(p_user uuid, p_ref text) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT coalesce(
      (SELECT encode(sha256(a.salt || uuid_send(p_user)), 'hex') = p_ref
       FROM audit_actor_salt a WHERE a.user_id = p_user),
      false)
  $$;--> statement-breakpoint
DO $$
  DECLARE
    broken record;
  BEGIN
    SELECT c.workspace_id, c.id INTO broken FROM (
      SELECT a.workspace_id, a.id,
             a.hash = sha256(coalesce(a.prev_hash, ''::bytea)
                             || convert_to(app_audit_canonical(a)::text, 'UTF8')) AS hash_ok,
             CASE WHEN row_number() OVER w = 1 THEN true
                  ELSE a.prev_hash IS NOT DISTINCT FROM lag(a.hash) OVER w END AS link_ok
      FROM audit_event a
      WINDOW w AS (PARTITION BY a.workspace_id ORDER BY a.created_at, a.id)
    ) c
    WHERE NOT c.hash_ok OR NOT c.link_ok
    LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'audit chain % is broken at event %; refusing to re-chain',
        coalesce(broken.workspace_id::text, 'account'), broken.id
        USING ERRCODE = 'data_corrupted';
    END IF;
  END
$$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION app_audit_canonical(e audit_event) RETURNS jsonb
  LANGUAGE sql STABLE PARALLEL SAFE SET search_path = public, pg_temp
  AS $$
    SELECT CASE WHEN e.actor_ref IS NULL THEN o
                ELSE (o - 'actor_user_id') || jsonb_build_object('actor_ref', e.actor_ref) END
    FROM (SELECT jsonb_build_object(
      'id', e.id,
      'workspace_id', e.workspace_id,
      'actor_user_id', e.actor_user_id,
      'actor_kind', e.actor_kind,
      'action', e.action,
      'target_kind', e.target_kind,
      'target_id', e.target_id,
      'outcome', e.outcome,
      'ip', host(e.ip),
      'user_agent_hash', e.user_agent_hash,
      'request_id', e.request_id,
      'metadata', e.metadata,
      'created_at', to_char(e.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
    ) AS o) c
  $$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION app_audit_append(
    p_workspace_id uuid,
    p_actor_user_id uuid,
    p_actor_kind audit_actor_kind,
    p_action text,
    p_target_kind text DEFAULT NULL,
    p_target_id text DEFAULT NULL,
    p_outcome audit_outcome DEFAULT 'success',
    p_ip inet DEFAULT NULL,
    p_user_agent_hash text DEFAULT NULL,
    p_request_id text DEFAULT NULL,
    p_metadata jsonb DEFAULT '{}'::jsonb
  ) RETURNS TABLE (id uuid, hash bytea)
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    #variable_conflict use_column
    DECLARE
      e audit_event;
    BEGIN
      IF p_workspace_id IS NOT NULL AND p_workspace_id IS DISTINCT FROM app_current_workspace() THEN
        RAISE EXCEPTION 'audit event for a workspace other than the pinned one'
          USING ERRCODE = 'insufficient_privilege';
      END IF;
      PERFORM pg_advisory_xact_lock(
        hashtextextended('audit_event:' || coalesce(p_workspace_id::text, 'account'), 0));
      SELECT a.hash INTO e.prev_hash FROM audit_event a
      WHERE a.workspace_id IS NOT DISTINCT FROM p_workspace_id
      ORDER BY a.created_at DESC, a.id DESC
      LIMIT 1;
      e.id := app_uuid_v7();
      e.workspace_id := p_workspace_id;
      e.actor_user_id := p_actor_user_id;
      e.actor_ref := app_audit_actor_ref(p_actor_user_id);
      e.actor_kind := p_actor_kind;
      e.action := p_action;
      e.target_kind := p_target_kind;
      e.target_id := p_target_id;
      e.outcome := coalesce(p_outcome, 'success');
      e.ip := p_ip;
      e.user_agent_hash := p_user_agent_hash;
      e.request_id := p_request_id;
      e.metadata := coalesce(p_metadata, '{}'::jsonb);
      -- Taken after the lock, so created_at follows chain order.
      e.created_at := clock_timestamp();
      e.hash := sha256(coalesce(e.prev_hash, ''::bytea)
                       || convert_to(app_audit_canonical(e)::text, 'UTF8'));
      INSERT INTO audit_event SELECT (e).*;
      RETURN QUERY SELECT e.id, e.hash;
    END
  $$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION app_audit_immutable() RETURNS trigger
  LANGUAGE plpgsql SET search_path = public, pg_temp
  AS $$
    BEGIN
      IF TG_OP IN ('DELETE', 'TRUNCATE')
         AND current_setting('app.audit_retention', true) = 'on' THEN
        RETURN OLD;
      END IF;
      -- Nested so ai_call rows never evaluate audit_event columns.
      IF TG_OP = 'UPDATE' AND TG_TABLE_NAME = 'audit_event' THEN
        IF current_setting('app.audit_anonymise', true) = 'on'
           AND (to_jsonb(OLD) ->> 'actor_ref') IS NOT NULL
           AND (to_jsonb(NEW) ->> 'actor_user_id') IS NULL
           AND to_jsonb(NEW) - 'actor_user_id' = to_jsonb(OLD) - 'actor_user_id' THEN
          RETURN NEW;
        END IF;
        IF current_setting('app.audit_rechain', true) = 'on'
           AND to_jsonb(NEW) - 'actor_ref' - 'prev_hash' - 'hash'
               = to_jsonb(OLD) - 'actor_ref' - 'prev_hash' - 'hash' THEN
          RETURN NEW;
        END IF;
      END IF;
      RAISE EXCEPTION '% is append-only: % is not allowed', TG_TABLE_NAME, TG_OP
        USING ERRCODE = 'insufficient_privilege';
    END
  $$;--> statement-breakpoint
CREATE POLICY "owner_definer_anonymise" ON "audit_event" AS PERMISSIVE FOR UPDATE TO causedeck_owner
  USING (true) WITH CHECK (true);--> statement-breakpoint
DO $$
  DECLARE
    r audit_event;
    chain uuid;
    first boolean;
    prev bytea;
    last_chain text := NULL;
  BEGIN
    PERFORM set_config('app.audit_rechain', 'on', true);
    FOR r IN SELECT * FROM audit_event a ORDER BY a.workspace_id NULLS FIRST, a.created_at, a.id LOOP
      first := last_chain IS DISTINCT FROM coalesce(r.workspace_id::text, 'account');
      last_chain := coalesce(r.workspace_id::text, 'account');
      IF NOT first THEN
        r.prev_hash := prev;
      END IF;
      IF r.actor_user_id IS NOT NULL AND r.actor_ref IS NULL THEN
        r.actor_ref := app_audit_actor_ref(r.actor_user_id);
      END IF;
      r.hash := sha256(coalesce(r.prev_hash, ''::bytea)
                       || convert_to(app_audit_canonical(r)::text, 'UTF8'));
      UPDATE audit_event a
        SET actor_ref = r.actor_ref, prev_hash = r.prev_hash, hash = r.hash
        WHERE a.id = r.id
          AND (a.actor_ref IS DISTINCT FROM r.actor_ref OR a.prev_hash IS DISTINCT FROM r.prev_hash
               OR a.hash IS DISTINCT FROM r.hash);
      prev := r.hash;
    END LOOP;
    PERFORM set_config('app.audit_rechain', '', true);
  END
$$;--> statement-breakpoint
CREATE FUNCTION app_audit_anonymise_actor(p_user uuid) RETURNS bigint
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    DECLARE
      n bigint;
    BEGIN
      IF p_user IS NULL OR EXISTS (SELECT 1 FROM "user" u WHERE u.id = p_user) THEN
        RAISE EXCEPTION 'audit events are anonymised only for a deleted account'
          USING ERRCODE = 'insufficient_privilege';
      END IF;
      PERFORM set_config('app.audit_anonymise', 'on', true);
      UPDATE audit_event a SET actor_user_id = NULL
        WHERE a.actor_user_id = p_user AND a.actor_ref IS NOT NULL;
      GET DIAGNOSTICS n = ROW_COUNT;
      PERFORM set_config('app.audit_anonymise', '', true);
      DELETE FROM audit_actor_salt s WHERE s.user_id = p_user;
      RETURN n;
    END
  $$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION app_audit_verify_account_chain(p_from timestamptz, p_to timestamptz)
  RETURNS TABLE (checked int, id uuid, reason text)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    WITH c AS (
      SELECT a.id, a.created_at,
             a.hash = sha256(coalesce(a.prev_hash, ''::bytea)
                             || convert_to(app_audit_canonical(a)::text, 'UTF8')) AS hash_ok,
             CASE WHEN row_number() OVER w = 1
                  THEN p_from IS NOT NULL OR a.prev_hash IS NULL
                  ELSE a.prev_hash IS NOT DISTINCT FROM lag(a.hash) OVER w END AS link_ok,
             (a.actor_user_id IS NULL OR a.actor_ref IS NULL
              OR app_audit_actor_ref_matches(a.actor_user_id, a.actor_ref)) AS actor_ok
      FROM audit_event a
      WHERE a.workspace_id IS NULL
        AND (p_from IS NULL OR a.created_at >= p_from)
        AND (p_to IS NULL OR a.created_at < p_to)
      WINDOW w AS (ORDER BY a.created_at, a.id)
    )
    SELECT n.checked, b.id, b.reason
    FROM (SELECT count(*)::int AS checked FROM c) n
    LEFT JOIN LATERAL (
      SELECT c.id, CASE WHEN NOT c.hash_ok THEN 'hash' WHEN NOT c.link_ok THEN 'link'
                        ELSE 'actor' END AS reason
      FROM c WHERE NOT c.hash_ok OR NOT c.link_ok OR NOT c.actor_ok
      ORDER BY c.created_at, c.id LIMIT 1
    ) b ON true
  $$;--> statement-breakpoint
CREATE POLICY "account_self" ON "deletion_job" AS PERMISSIVE FOR ALL TO PUBLIC
  USING (app_current_workspace() IS NULL AND workspace_id IS NULL AND kind = 'account'
         AND user_id = app_current_user())
  WITH CHECK (app_current_workspace() IS NULL AND workspace_id IS NULL AND kind = 'account'
